import { createTabs } from '@benosjs/primitives/tabs'
import { mergeProps, splitProps } from '@benosjs/dom'
import type { Child, JSX } from '@benosjs/dom'
import type { TabsOptions } from '@benosjs/primitives/tabs'

export interface TabsItem {
  value: string
  label: string
  content: Child
  disabled?: boolean
}

export type TabsProps = Pick<
  TabsOptions,
  | 'value'
  | 'defaultValue'
  | 'orientation'
  | 'activationMode'
  | 'loopFocus'
  | 'dir'
  | 'onValueChange'
> & {
  id?: string
  class?: string
  label: string
  items: readonly TabsItem[]
  title?: string
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-describedby'?: string
  ref?: (element: HTMLDivElement) => void
}

export function Tabs(props: TabsProps): JSX.Element {
  const merged = mergeProps(
    {
      orientation: 'horizontal' as const,
      activationMode: 'automatic' as const,
    },
    props,
  )
  const [local, native] = splitProps(merged, [
    'id',
    'class',
    'ref',
    'label',
    'items',
    'value',
    'defaultValue',
    'orientation',
    'activationMode',
    'loopFocus',
    'dir',
    'onValueChange',
  ] as const)
  const machine = createTabs(() => {
    const defaultValue = local.defaultValue ?? local.items[0]?.value
    return {
      ...(local.id === undefined ? {} : { id: local.id }),
      ...(local.value === undefined ? {} : { value: local.value }),
      ...(defaultValue === undefined ? {} : { defaultValue }),
      orientation: local.orientation,
      activationMode: local.activationMode,
      ...(local.loopFocus === undefined ? {} : { loopFocus: local.loopFocus }),
      ...(local.dir === undefined ? {} : { dir: local.dir }),
      ...(local.onValueChange === undefined ? {} : { onValueChange: local.onValueChange }),
    }
  })
  const api = machine.api
  const root = api().getRootProps()
  const rootRef = root.ref as ((element: HTMLDivElement) => void) | undefined
  const ref = (element: HTMLDivElement) => {
    rootRef?.(element)
    local.ref?.(element)
  }
  const labelId = `benos-tabs-label-${local.id ?? String(root.id)}`

  return (
    <div
      {...root}
      {...native}
      id={local.id}
      dir={local.dir}
      class={['benos-tabs', local.class].filter(Boolean).join(' ')}
      ref={ref}
    >
      <div class="benos-tabs__label" id={labelId}>
        {local.label}
      </div>
      <div
        class="benos-tabs__list"
        aria-labelledby={labelId}
        {...api().getListProps()}
        dir={local.dir}
      >
        {local.items.map((item) => (
          <button
            class="benos-tabs__trigger"
            type="button"
            {...api().getTriggerProps({
              value: item.value,
              disabled: item.disabled,
            })}
            dir={local.dir}
          >
            {item.label}
          </button>
        ))}
      </div>
      {local.items.map((item) => (
        <div
          class="benos-tabs__panel"
          {...api().getContentProps({ value: item.value })}
          dir={local.dir}
        >
          {item.content}
        </div>
      ))}
    </div>
  )
}

.benos-tabs {
  color: var(--benos-color-text);
  display: grid;
  font-size: var(--benos-text-xs, 0.75rem);
  gap: var(--benos-space-3);
}

.benos-tabs__label {
  font-size: var(--benos-text-xs, 0.75rem);
  font-weight: 600;
}

.benos-tabs__list {
  border-block-end: 1px solid var(--benos-color-border);
  display: flex;
  gap: var(--benos-space-1);
}

.benos-tabs[data-orientation='vertical'] {
  grid-template-columns: auto 1fr;
}

.benos-tabs[data-orientation='vertical'] .benos-tabs__label {
  grid-column: 1 / -1;
}

.benos-tabs[data-orientation='vertical'] .benos-tabs__list {
  border-block-end: 0;
  border-inline-end: 1px solid var(--benos-color-border);
  flex-direction: column;
}

.benos-tabs__trigger {
  background: transparent;
  border: 0;
  border-block-end: 2px solid transparent;
  color: var(--benos-color-text-muted);
  cursor: pointer;
  font: inherit;
  margin-block-end: -1px;
  padding-block: var(--benos-space-2);
  padding-inline: var(--benos-space-3);
}

.benos-tabs__trigger[data-selected] {
  border-color: var(--benos-color-brand);
  color: var(--benos-color-text);
}

.benos-tabs__trigger:focus-visible {
  border-radius: var(--benos-radius-sm);
  outline: 3px solid var(--benos-color-focus);
  outline-offset: 2px;
}

.benos-tabs__trigger[data-disabled] {
  cursor: not-allowed;
  opacity: 0.58;
}

.benos-tabs__panel {
  line-height: var(--benos-line-height-body);
}

.benos-tabs__panel[hidden] {
  display: none;
}
